func check(ctx Context, res Value, p Value, x ...Value) {
	var tx Value
	switch t := unloc(p).(type) {
	case *delegate: tx = t.x
	case *closure: tx = t.x
	}
	if rxIgnoredAutos.MatchString(tx.String()) { return }

	source := try[string](ctx,source{})
	src := strings.Split(source, ":")
	if src == nil { src = []string{""} }

	spec := func() (s string) {
		if j := _project(ctx); j != nil { s = j.spec }
		for strings.HasPrefix(s, "../") { s = strings.TrimPrefix(s, "../") }
		return
	} ()

	d, _ := do(ctx, origin_def{}).(*def)

	k := func() (s string) {
		if false && 2 == len(src) && src[0] != "loader.go" { s = src[1] + " " }
		if false && d != nil { s += line_column(d)+":"+d.name+" " }
		s += p.String()+" "+ts(p)
		return
	} ()

	v := func() string {
		switch expected := checkspecs[spec][k].(type) {
		case unwrap_loc_part:
			// Dynamically find all {=unwrap-loc-XXX } markers the expected string requested
			marker := regexp.MustCompile(`\{=unwrap-loc-([^\s{}]+)\s`)
			matches := marker.FindAllStringSubmatch(string(expected), -1)

			s := ts(res, ctx)
			seen := make(map[string]bool)
			for _, m := range matches {
				tag := m[1] // e.g., "path", "list", etc.
				if seen[tag] { continue }
				seen[tag] = true
				
				searchTag := "{=" + tag + " "
				replaceTag := "{=unwrap-loc-" + tag + " "
				
				// Split the ACTUAL AST string by the standard tag, unwrap the contents,
				// and re-join with the marker
				parts := strings.Split(s, searchTag)
				for i := 1; i < len(parts); i++ {
					parts[i] = unwrapLocStr(parts[i])
				}
				s = strings.Join(parts, replaceTag)
			}
			return sf("%v %s", res, s)
		}
		return sf("%v %s", res, ts(res, ctx))
	} ()

	t := func() any {
		switch t := checkspecs[spec][k].(type) {
		case sorted_list:
			if l, ok := res.(*list); ok {
				sort.Slice(l.elems, func(i, j int) bool {
					return l.elems[i].String() < l.elems[j].String()
				})
			}
			return []string(t)
		case unwrap_loc_part:
			return string(t) // Cast to string so the lower switch can match it against `v`
		case map[string]any, map[string]string:
			debug(pc(pc(ctx,res),p), "%v %v", k, t)
			return nil
		default:
			return t
		}
	} ()

	if p.String() == res.String() { return }

	if t == nil {
		if j := _project(ctx); j != nil { switch {
		case strings.HasSuffix(j.spec, ".smart/modules/lib/unwind"): return
		case strings.HasSuffix(j.spec, ".smart/modules/lib/c++abi"): return
		case strings.HasSuffix(j.spec, ".smart/modules/lib/c++inc"): return
		case strings.HasSuffix(j.spec, ".smart/modules/lib/c++"): return
		case strings.HasSuffix(j.spec, ".smart/modules/sys"): return
		case strings.HasSuffix(j.spec, ".smart/modules/sys/dl"): return
		case strings.HasSuffix(j.spec, ".smart/modules/sys/pthread"): return
		case strings.HasSuffix(j.spec, ".smart/modules/configure"): return
		case strings.HasSuffix(j.spec, "testdata/configuration/two"): return
		case strings.HasSuffix(j.spec, "testdata/configuration"): return
		}}
		debug(pc(pc(ctx,res),p),
			_f("`%v`:`%v`,", k, v),
			_f(`note: %v "%s"`, source, spec),
			callstack{stop:"smart.runcase"}, trace{})
	} else {
		switch t := t.(type) {
		case []string: for _, s := range t { if s == v { return } }
		case string: if t == v { return }
		}
		debug(pc(pc(ctx,res),p),
			_f("`%v`", k),
			_f(`got: %s`, v),
			_f(`!= : %v`, t),
			_f(`note: %v "%s"`, source, spec),
			callstack{stop:"smart.runcase"}, trace{})
	}
}

