func tempdir_check(ctx Context, p *project, d *def, s string) {
	switch p.name {
	case "testdefaultconfigure":
		if d.name != "outtmp" {
			debug(ctx,
				_f("wrong tempdir: %v", d),
				_f("%v", p.resolveDef(ctx, "outtmp")),
				_f("%s %s %v", p.name, p.spec, p.bases),
				callstack{num:16}, trace{})
		}
		if t := p.resolveDef(ctx, "target.tmp"); __string(ctx, t) == "" {
			debug(ctx, "wrong tempdir: %v ; %v", d, t, callstack{num:16}, trace{})
		}
		if s == "/" {
			erro(ctx, "wrong tempdir: %v → %s", d, s)

			var t *def

			t = p.resolveDef(ctx, "target.tmp")
			note(ctx, "%v → %s", t, __string(ctx, t))

			t = p.resolveDef(ctx, "target.out")
			note(ctx, "%v → %s", t, __string(ctx, t))

			t = p.resolveDef(ctx, "target.triple")
			note(ctx, "%v → %s", t, __string(ctx, t))

			t = p.resolveDef(ctx, "rel.remnant")
			note(ctx, "%v → %s", t, __string(ctx, t))

			t = p.resolveDef(ctx, "rel.chop")
			note(ctx, "%v → %s", t, __string(ctx, t))

			t = p.resolveDef(ctx, "variant.tag")
			note(ctx, "%v → %s", t, __string(ctx, t), trace{})
		}
	}
}

func tempfile_check(ctx Context, p *project, name, d string, f *file) {
	if f.dir != d {
		debug(ctx, "%v: %s != %s", p, f.dir, d, trace{})
	}
	switch p.name {
	case "testdefaultconfigure":
		var t *def
		if t = p.resolveDef(ctx, "outtmp"); t == nil { // outtmp:=&(target.tmp)/&(rel.remnant)
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, callstack{num:10}, trace{})
		} else if s, t1 := "&(target.tmp)/&(rel.remnant)", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		} else if s, t2 := "/", __string(ctx, t); t2 == s {
			debug(ctx, "%s: %v : %s", p.name, d, t2, trace{})
		} else if t2 != f.dir {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t2, f.dir, trace{})
		}
		if t = p.resolveDef(ctx, "target.tmp"); t == nil { // target.tmp := &(target.out)/tmp
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "&(target.out)/tmp", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.out"); t == nil { // &(target.out)/tmp
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "$(workout)/&(target.triple)/&(variant.tag)", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		} else if s, t2 := "/Volumes/workout/arm64-apple-Darwin25.4.0-macho/bootstrap", __string(ctx, t); t2 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t2, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.triple"); t == nil { // target.tmp := &(target.out)/tmp
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "$(join &(target.arch)&(target.sub) &(target.vendor) &(target.sys) &(target.abi),-)", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		} else if s, t2 := "arm64-apple-Darwin25.4.0-macho", __string(ctx, t); t2 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t2, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.arch"); t == nil {
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "arm64", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		}
		if true {
			// ...
		} else if t = p.resolveDef(ctx, "target.sub"); t == nil {
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.vendor"); t == nil {
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "apple", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.sys"); t == nil {
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "&(uname.os)&(target.release)", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		} else if s, t2 := "Darwin25.4.0", __string(ctx, t); t2 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t2, s, trace{})
		}
		if t = p.resolveDef(ctx, "target.abi"); t == nil {
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if s, t1 := "macho", t.value.String(); t1 != s {
			debug(ctx, "%s: %v : %s != %s", p.name, d, t1, s, trace{})
		}
		if t = p.resolveDef(ctx, "rel.chop"); t == nil { // $(dir3 $/)/
			debug(ctx, "%s: %v : %s", p.name, d, f.dir, trace{})
		} else if pos, t0 := t.Position(), p.absPath+"/.base"; pos.Filename != t0 {
			debug(ctx, "%v : %s != %s", t.value, pos.Filename, t0, trace{})
		} else if s, t1 := dirs(2, p.absPath)+"/", t.value.String(); s != t1 {
			debug(ctx, "%v : %s != %s", t.value, s, t1, trace{})
		} else if t2 := __string(ctx, t); s != t2 {
			debug(ctx, "%v : %s != %s", t.value, s, t2, trace{})
		}
		if t = p.resolveDef(ctx, "rel.remnant"); t == nil { // $(trim-prefix &(rel.chop),&/)
			debug(ctx, "%s : %v", p.name, reflect.ValueOf(p.scope.elems).MapKeys(), callstack{num:10}, trace{})
		} else if s, t1 := "$(trim-prefix &(rel.chop),&/)", t.value.String(); s != t1 {
			debug(ctx, "%v : %s != %s", t.value, s, t1, trace{})
		} else if s, t2 := __string(closure_with(ctx, p.scope), t), bases(2, p.absPath); false && s != t2 {
			debug(ctx, "%v : %s != %s ; %v", t.value, s, t2, p.resolveDef(ctx, "rel.chop"), callstack{num:10}, trace{})
		}
	}
}
